import java.util.*;

public class Main {
    public static void main(String[] args) {
        WalletService walletService = new WalletService();
        walletService.createWallet("wallet-A", 1000);
        walletService.createWallet("wallet-B", 500);

        // A normal transfer with no contention and no holds in the way.
        TransferResult first = walletService.transfer("wallet-A", "wallet-B", 300);
        System.out.println("Transfer 1: " + first.status + ", attempts=" + first.attemptsUsed);
        System.out.println("  wallet-A balance=" + walletService.actualBalance("wallet-A") + " available=" + walletService.availableBalance("wallet-A"));
        System.out.println("  wallet-B balance=" + walletService.actualBalance("wallet-B"));

        // Place a hold on wallet-A, e.g. for a pending withdrawal, reducing its available balance.
        walletService.placeHold("wallet-A", 500);
        System.out.println("After a 500 hold, wallet-A available balance=" + walletService.availableBalance("wallet-A") + " (actual balance is still " + walletService.actualBalance("wallet-A") + ")");

        // This transfer should be denied: available balance (200) is less than the requested 300,
        // even though the actual balance (700) alone would be enough.
        TransferResult second = walletService.transfer("wallet-A", "wallet-B", 300);
        System.out.println("Transfer 2 (should be denied): " + second.status);

        // Release the hold, restoring wallet-A's available balance.
        walletService.releaseHold("wallet-A", 500);
        System.out.println("After releasing the hold, wallet-A available balance=" + walletService.availableBalance("wallet-A"));

        // Simulate a genuinely concurrent update landing between this transfer's read and its
        // own compare-and-swap commit attempt, e.g. a top up processed by another thread.
        walletService.debugInjectConcurrentUpdateOnce("wallet-A", 100);
        TransferResult third = walletService.transfer("wallet-A", "wallet-B", 300);
        System.out.println("Transfer 3 (hits one simulated version conflict, then retries): " + third.status + ", attempts=" + third.attemptsUsed);
        System.out.println("  wallet-A final balance=" + walletService.actualBalance("wallet-A"));
        System.out.println("  wallet-B final balance=" + walletService.actualBalance("wallet-B"));
    }
}

// The outcome of a transfer attempt, including how many compare-and-swap
// attempts it took to commit, to make the retry behavior visible.
class TransferResult {
    String status;
    int attemptsUsed;

    TransferResult(String status, int attemptsUsed) {
        this.status = status;
        this.attemptsUsed = attemptsUsed;
    }
}

// One wallet's durable state: its actual balance, any amount currently held
// for a pending operation, and a version number used for optimistic concurrency.
class Wallet {
    long balance;      // the true, settled balance
    long held;          // funds reserved for a pending operation, not spendable
    int version;          // incremented on every committed balance-changing write

    Wallet(long balance) {
        this.balance = balance;
        this.held = 0;
        this.version = 0;
    }
}

// Manages wallets with optimistic concurrency control: every balance-changing
// write reads a version number and commits only if it is still unchanged,
// retrying against fresh state whenever a concurrent update wins the race.
class WalletService {
    private final Map<String, Wallet> wallets = new HashMap<>();
    private String pendingRaceWalletId = null; // one-shot hook, armed by debugInjectConcurrentUpdateOnce
    private long pendingRaceAmount = 0;

    void createWallet(String walletId, long initialBalance) {
        wallets.put(walletId, new Wallet(initialBalance));
    }

    long actualBalance(String walletId) {
        return wallets.get(walletId).balance;
    }

    // Available balance is what a transfer is actually checked against, never
    // the actual balance alone, so held funds can never be double spent.
    long availableBalance(String walletId) {
        Wallet wallet = wallets.get(walletId);
        return wallet.balance - wallet.held;
    }

    void placeHold(String walletId, long amount) {
        wallets.get(walletId).held += amount; // reserve funds, reducing available balance without touching actual balance
    }

    void releaseHold(String walletId, long amount) {
        wallets.get(walletId).held -= amount; // release the reservation, restoring available balance
    }

    // Arms a one-time simulated concurrent update, purely to deterministically
    // demonstrate the compare-and-swap retry path in this single-threaded demo;
    // in production this same conflict would arise naturally from real concurrent requests.
    void debugInjectConcurrentUpdateOnce(String walletId, long simulatedConcurrentTopUp) {
        this.pendingRaceWalletId = walletId;
        this.pendingRaceAmount = simulatedConcurrentTopUp;
    }

    // Transfers amount from fromWalletId to toWalletId using optimistic concurrency
    // control: reads balance and version, then commits only if the version is
    // still unchanged, retrying with fresh state on a version mismatch.
    TransferResult transfer(String fromWalletId, String toWalletId, long amount) {
        int attempts = 0;
        while (true) {
            attempts++;
            Wallet from = wallets.get(fromWalletId);
            int seenVersion = from.version;                          // the version this attempt is based on
            long available = from.balance - from.held;                  // available balance at the moment of this read

            if (available < amount) {
                return new TransferResult("DENIED_INSUFFICIENT_AVAILABLE_BALANCE", attempts);
            }

            // Deterministically simulate a concurrent update landing between this
            // read and this attempt's own commit, exactly once, if armed.
            if (fromWalletId.equals(pendingRaceWalletId)) {
                from.balance += pendingRaceAmount; // some other operation's change, already committed
                from.version += 1;                    // its own version bump
                pendingRaceWalletId = null;             // fire only once
            }

            boolean committed = compareAndSwapDebit(fromWalletId, seenVersion, amount);
            if (committed) {
                creditWallet(toWalletId, amount);
                return new TransferResult("SUCCESS", attempts);
            }
