        }
    }

    private boolean compareAndSwapDebit(String walletId, int expectedVersion, long amount) {
        Wallet wallet = wallets.get(walletId);
        if (wallet.version != expectedVersion) {
            return false; // the version changed since this attempt's read; reject, caller will retry
        }
        wallet.balance -= amount; // commit the debit
        wallet.version++;           // advance the version so any other concurrent attempt now correctly fails
        return true;
    }

    private void creditWallet(String walletId, long amount) {
        Wallet wallet = wallets.get(walletId);
        wallet.balance += amount;
        wallet.version++;
    }
}

