        wallets_.emplace(walletId, Wallet(initialBalance));
    }

    long long actualBalance(const std::string& walletId) { return wallets_.at(walletId).balance; }

    // Available balance is what a transfer is actually checked against, never
    // the actual balance alone, so held funds can never be double spent.
    long long availableBalance(const std::string& walletId) {
        Wallet& wallet = wallets_.at(walletId);
        return wallet.balance - wallet.held;
