    void debugInjectConcurrentUpdateOnce(const std::string& walletId, long long simulatedConcurrentTopUp) {
        pendingRaceWalletId_ = walletId;
        pendingRaceAmount_ = simulatedConcurrentTopUp;
        hasPendingRace_ = true;
    }

